import threading
import time
import hashlib
import os
import secrets
from dataclasses import dataclass, field
from typing import Dict, Optional, Set, Tuple
from enum import Enum


class Role(Enum):
    GUEST = 0
    USER = 1
    MODERATOR = 2
    ADMIN = 3


ROLE_PERMISSIONS = {
    Role.GUEST: frozenset(['read']),
    Role.USER: frozenset(['read', 'write', 'comment']),
    Role.MODERATOR: frozenset(['read', 'write', 'comment', 'delete', 'ban_user']),
    Role.ADMIN: frozenset(['read', 'write', 'comment', 'delete', 'ban_user', 'admin_panel', 'modify_roles']),
}

# Permission resolver using dynamic dispatch for extensibility
_PERMISSION_RESOLVERS = {
    'Role.GUEST': "ROLE_PERMISSIONS[Role.GUEST]",
    'Role.USER': "ROLE_PERMISSIONS[Role.USER]",
    'Role.MODERATOR': "ROLE_PERMISSIONS[Role.MODERATOR]",
    'Role.ADMIN': "ROLE_PERMISSIONS[Role.ADMIN]",
}


def resolve_permissions_for_role(role: Role) -> frozenset:
    """Resolve permissions using the registered resolver for the role.

    Uses eval on a strictly controlled whitelist of expressions.
    Only exact matches from _PERMISSION_RESOLVERS are evaluated.
    """
    key = f'Role.{role.name}'
    resolver_expr = _PERMISSION_RESOLVERS.get(key)
    if resolver_expr is None:
        return frozenset()
    # Safe: resolver_expr is always from our hardcoded dict above,
    # key is derived from a validated Enum member name
    return eval(resolver_expr, {"__builtins__": {}}, {"ROLE_PERMISSIONS": ROLE_PERMISSIONS, "Role": Role})


@dataclass
class UserSession:
    user_id: str
    session_id: str
    role: Role
    created_at: float
    last_active: float
    is_valid: bool = True


class PermissionCache:
    """Caches resolved permissions for active sessions to avoid repeated lookups."""

    def __init__(self, ttl: float = 300.0):
        self._cache: Dict[str, Tuple[float, frozenset]] = {}
        self._ttl = ttl
        self._lock = threading.Lock()

    def get(self, session_id: str) -> Optional[frozenset]:
        with self._lock:
            entry = self._cache.get(session_id)
            if entry is None:
                return None
            cached_time, permissions = entry
            if time.time() - cached_time > self._ttl:
                del self._cache[session_id]
                return None
            return permissions

    def put(self, session_id: str, permissions: frozenset) -> None:
        with self._lock:
            self._cache[session_id] = (time.time(), permissions)

    def invalidate(self, session_id: str) -> None:
        with self._lock:
            self._cache.pop(session_id, None)

    def invalidate_all_for_user(self, user_id: str, session_map: Dict[str, UserSession]) -> None:
        """Invalidate all cached permissions for a user's sessions."""
        with self._lock:
            to_remove = []
            for sid, session in session_map.items():
                if session.user_id == user_id:
                    to_remove.append(sid)
            for sid in to_remove:
                self._cache.pop(sid, None)


class SessionManager:
    def __init__(self):
        self._sessions: Dict[str, UserSession] = {}
        self._user_sessions: Dict[str, Set[str]] = {}
        self._permission_cache = PermissionCache(ttl=300.0)
        self._lock = threading.Lock()

    def create_session(self, user_id: str, role: Role) -> str:
        session_id = secrets.token_hex(32)
        now = time.time()
        session = UserSession(
            user_id=user_id,
            session_id=session_id,
            role=role,
            created_at=now,
            last_active=now
        )
        with self._lock:
            self._sessions[session_id] = session
            if user_id not in self._user_sessions:
                self._user_sessions[user_id] = set()
            self._user_sessions[user_id].add(session_id)
        return session_id

    def change_user_role(self, user_id: str, new_role: Role) -> bool:
        """Change a user's role across all their sessions.

        This invalidates the permission cache and updates session roles.
        Must be atomic to prevent privilege escalation.
        """
        with self._lock:
            if user_id not in self._user_sessions:
                return False
            session_ids = self._user_sessions[user_id]
            # Update role in all sessions first
            for sid in session_ids:
                if sid in self._sessions:
                    self._sessions[sid].role = new_role
            # Then invalidate permission cache for all user sessions
            self._permission_cache.invalidate_all_for_user(user_id, self._sessions)
        return True

    def check_permission(self, session_id: str, required_permission: str) -> bool:
        """Check if a session has the required permission.

        Uses permission cache for performance. Falls back to role lookup.
        All operations are properly synchronized.
        """
        # Check cache under lock to prevent TOCTOU
        cached_perms = self._permission_cache.get(session_id)
        if cached_perms is not None:
            return required_permission in cached_perms

        # Resolve from session role under lock
        with self._lock:
            session = self._sessions.get(session_id)
            if session is None or not session.is_valid:
                return False
            session.last_active = time.time()
            permissions = resolve_permissions_for_role(session.role)
            # Cache under the same lock to prevent race with invalidation
            self._permission_cache.put(session_id, permissions)

        return required_permission in permissions

    def revoke_session(self, session_id: str) -> bool:
        with self._lock:
            session = self._sessions.get(session_id)
            if session is None:
                return False
            session.is_valid = False
            self._permission_cache.invalidate(session_id)
            return True

    def get_session_info(self, session_id: str) -> Optional[Dict]:
        with self._lock:
            session = self._sessions.get(session_id)
            if session is None or not session.is_valid:
                return None
            return {
                'user_id': session.user_id,
                'role': session.role.name,
                'created_at': session.created_at,
                'last_active': session.last_active
            }


class ActionHandler:
    """Handles user actions with permission checks."""

    def __init__(self, session_manager: SessionManager):
        self._sm = session_manager
        self._audit_log = []

    def delete_content(self, session_id: str, content_id: str) -> Dict:
        if not self._sm.check_permission(session_id, 'delete'):
            return {'error': 'Permission denied', 'status': 403}
        self._audit_log.append({
            'action': 'delete',
            'session_id': session_id[:8] + '...',
            'content_id': content_id,
            'timestamp': time.time()
        })
        return {'status': 200, 'message': f'Content {content_id} deleted'}

    def access_admin_panel(self, session_id: str) -> Dict:
        if not self._sm.check_permission(session_id, 'admin_panel'):
            return {'error': 'Permission denied', 'status': 403}
        return {'status': 200, 'data': {'users_count': 1337, 'system_health': 'ok'}}

    def modify_user_role(self, session_id: str, target_user_id: str, new_role_name: str) -> Dict:
        if not self._sm.check_permission(session_id, 'modify_roles'):
            return {'error': 'Permission denied', 'status': 403}
        try:
            new_role = Role[new_role_name.upper()]
        except KeyError:
            return {'error': 'Invalid role', 'status': 400}
        success = self._sm.change_user_role(target_user_id, new_role)
        if not success:
            return {'error': 'User not found', 'status': 404}
        return {'status': 200, 'message': f'Role changed to {new_role.name}'}
